library(shiny)

refs <- data.frame(
  name = c(
    "ESC/ERS PH guideline (2022)",
    "7th WSPH diagnostic update (2024)",
    "7th WSPH PAH treatment algorithm (2024)",
    "ERS PAH treatment update (2026)",
    "INCREASE PH-ILD trial",
    "SIOVAC PH-LHD trial",
    "RACE CTEPH trial"
  ),
  doi = c(
    "10.1183/13993003.00879-2022",
    "10.1183/13993003.01324-2024",
    "10.1183/13993003.01325-2024",
    "10.1183/13993003.01178-2026",
    "10.1056/NEJMoa2008470",
    "10.1093/eurheartj/ehx700",
    "10.1016/S2213-2600(22)00214-4"
  ),
  stringsAsFactors = FALSE
)

drugs_data <- list(
  list(
    pathway = "no_cgmp",
    name = "Sildenafil",
    group_label = "PDE5 inhibitor (Oral)",
    en_status = "Widely available in Thailand (listed in NLEM E(2) for PAH under specified criteria)",
    dosing_en = "20 mg PO TID (standard adult dose; higher titration occasionally used in specialist centres)",
    side_effects_en = "Headache, flushing, dyspepsia, epistaxis, nasal congestion, hypotension, transient visual/color disturbance",
    cautions_en = "CONTRAINDICATED with nitrates and riociguat (severe hypotension) · Caution with strong CYP3A4 inhibitors; bosentan decreases sildenafil plasma levels."
