  list(
    pathway = "no_cgmp",
    name = "Tadalafil",
    group_label = "PDE5 inhibitor (Oral)",
    en_status = "Available in Thailand (tertiary/university/private hospitals; non-NLEM)",
    dosing_en = "Start 20 mg PO OD, titrate to target 40 mg PO OD",
    side_effects_en = "Headache, myalgia/back pain, flushing, dyspepsia, nasal congestion",
    cautions_en = "CONTRAINDICATED with nitrates and riociguat · Adjust dose in mild-to-moderate renal impairment; avoid if CrCl <30 mL/min or severe hepatic cirrhosis (Child-Pugh C)."
  ),
  list(
    pathway = "no_cgmp",
    name = "Riociguat",
    group_label = "Soluble Guanylate Cyclase (sGC) Stimulator (Oral)",
    en_status = "Available in specialist centres in Thailand (indicated for inoperable/persistent CTEPH and PAH; non-NLEM)",
    dosing_en = "Start 0.5–1.0 mg PO TID; titrate by 0.5 mg every 2 weeks (if SBP >=95 mmHg and no hypotension symptoms) up to max 2.5 mg PO TID",
    side_effects_en = "Hypotension, dizziness, headache, dyspepsia/GI upset, peripheral edema, hemoptysis/bleeding",
    cautions_en = "STRICTLY CONTRAINDICATED in pregnancy (teratogenic), with PDE5i (washout >=24h for sildenafil, >=48h for tadalafil), with nitrates, and in PH-IIP (RISE-IIP) · Smoking reduces plasma concentration."
  ),
  list(
    pathway = "era",
    name = "Bosentan",
    group_label = "Endothelin Receptor Antagonist — Dual ETA/ETB (Oral)",
    en_status = "Widely available in Thailand (listed in NLEM E(2) for PAH under specified criteria)",
    dosing_en = "Start 62.5 mg PO BID for 4 weeks, then increase to maintenance 125 mg PO BID (adults >40 kg)",
    side_effects_en = "Dose-dependent hepatic aminotransferases elevation (~10%), peripheral edema/fluid retention, anemia (hemodilution), headache, flushing",
    cautions_en = "STRICTLY CONTRAINDICATED in pregnancy (teratogenic; reduces hormonal contraceptive efficacy via CYP3A4/2C9 induction — require dual contraception) · Mandatory monthly LFT monitoring and periodic Hb checks · Contraindicated with cyclosporine A and glibenclamide."
  ),
  list(
    pathway = "era",
    name = "Macitentan",
