    side_effects_en = "Cough, throat irritation, flushing, headache, jaw pain, hypotension/syncope, bronchospasm",
    cautions_en = "Requires frequent dosing (6–9 inhalations/day) due to short half-life · Monitor for bronchospasm and systemic hypotension."
  ),
