server <- function(input, output, session) {

  observeEvent(input$reset_echo, {
    updateNumericInput(session, "trv", value = NA)
    updateCheckboxInput(session, "echo_signs", value = FALSE)
    updateCheckboxInput(session, "redflag", value = FALSE)
  })

  observeEvent(input$reset_rhc, {
    updateNumericInput(session, "mpap", value = NA)
    updateNumericInput(session, "pawp", value = NA)
    updateNumericInput(session, "co", value = NA)
    updateNumericInput(session, "pvr", value = NA)
  })

  output$echo_out <- renderUI({
    t <- input$trv
    s <- isTRUE(input$echo_signs)
    rf <- isTRUE(input$redflag)

    if (!is.null(t) && !is.na(t) && (t < 0 || t > 7)) {
      return(div(class = "danger-note", strong("Invalid TRV: "), "Enter a peak TRV between 0 and 7 m/s, or leave blank if unmeasurable."))
    }

    prob <- if (is.null(t) || is.na(t)) {
      if (s) "Intermediate (unmeasurable TRV with signs in >=2 categories)" else "Low by simplified rule; PH is NOT excluded"
    } else if (t > 3.4) {
      "High"
    } else if (t > 2.8) {
      if (s) "High" else "Intermediate"
    } else {
      if (s) "Intermediate" else "Low"
    }

    box_class <- if (rf || prob == "High") {
      "danger-note"
    } else if (grepl("^Intermediate", prob)) {
      "alert-note"
    } else {
      "ok-note"
    }

    action_text <- if (rf) {
      "URGENT PH-centre assessment is indicated due to clinical red flags."
    } else if (prob == "High" || grepl("^Intermediate", prob)) {
      "Further investigation indicated. Consider RHC if PAH or CTEPH is suspected or if results will change management."
    } else {
      "Consider alternative causes of symptoms or echo follow-up if clinical suspicion or PAH/CTEPH risk factors persist."
    }

    div(
      class = box_class,
      div(strong("Estimated echocardiographic probability: "), prob),
      div(style = "margin-top:4px;", action_text)
    )
  })

  output$rhc_out <- renderUI({
    m <- input$mpap
    w <- input$pawp
    cardiac_output <- input$co
    p <- input$pvr

    if (any(is.na(c(m, w))) || m < 0 || w < 0) {
      return(div(class = "step", "Enter valid resting mPAP and PAWP to classify hemodynamics."))
    }
    if (w > m) {
      return(div(class = "danger-note", strong("Inconsistent: "), "PAWP exceeds mPAP. Verify pressure zeroing and measurements."))
    }

    derived <- if (!is.na(cardiac_output) && cardiac_output > 0) (m - w) / cardiac_output else NA_real_
    if (is.na(p)) p <- derived

    if (m <= 20) {
      return(div(
        class = "ok-note",
        strong("Resting PH criterion not met (mPAP <=20 mmHg). "),
        "Interpret in clinical context."
      ))
    }

    if (is.na(p)) {
      return(div(
        class = "alert-note",
        strong("PH present (mPAP >20 mmHg). "),
        "Enter Cardiac Output or PVR to classify pre- vs post-capillary hemodynamics."
      ))
    }

    if (p < 0) {
      return(div(class = "danger-note", strong("Invalid negative PVR. "), "Verify entered data."))
    }

    typ <- if (w <= 15 && p > 2) {
      "Pre-capillary PH (mPAP >20 mmHg, PAWP <=15 mmHg, PVR >2 WU)"
    } else if (w > 15 && p <= 2) {
      "Isolated post-capillary PH — IpcPH (mPAP >20 mmHg, PAWP >15 mmHg, PVR <=2 WU)"
    } else if (w > 15 && p > 2) {
      "Combined post- and pre-capillary PH — CpcPH (mPAP >20 mmHg, PAWP >15 mmHg, PVR >2 WU)"
    } else {
      "Unclassified PH (mPAP >20 mmHg, PAWP <=15 mmHg, PVR <=2 WU) — consider elevated pulmonary blood flow / high cardiac output or other mechanisms."
    }

    has_mismatch <- !is.na(derived) && !is.na(input$pvr) && abs(derived - input$pvr) > max(0.5, 0.2 * derived)
    severe_note <- if (p > 5) "Severe hemodynamic elevation (PVR >5 WU; threshold for severe PH in lung disease / complex CpcPH)." else NULL

    div(
      class = if (p > 5) "danger-note" else "alert-note",
      div(strong("Classification: "), typ),
      div(
        style = "margin-top:4px;",
        strong("PVR: "), paste0(round(p, 2), " WU"),
        if (!is.na(derived) && !is.na(input$pvr)) paste0(" (calculated from CO: ", round(derived, 2), " WU)") else ""
      ),
      if (!is.null(severe_note)) div(style = "margin-top:4px;font-weight:600;", severe_note),
      if (has_mismatch) div(
        style = "margin-top:6px;color:#a12626;font-weight:600;",
        "WARNING: Entered PVR differs from calculated (mPAP - PAWP) / CO; verify CO and measurements."
      ),
      div(style = "margin-top:6px;font-size:13px;", "Note: Hemodynamics alone do not establish the clinical PH group. Integrate with clinical context, imaging, PFTs, and V/Q scan.")
    )
  })

  investigations <- list(
    "Unclear / undifferentiated" = c(
      "History, exam, ECG, SpO2, BNP/NT-proBNP, echocardiography.",
      "PFT with DLCO, chest radiograph, HRCT/CT as indicated.",
      "V/Q scan in unexplained PH to assess CTEPH.",
      "RHC when clinically indicated; consider specialist referral."
    ),
    "PAH / Group 1" = c(
      "Confirm pre-capillary PH by RHC and exclude Groups 2–4.",
      "Assess CTD (including ANA/targeted serology), HIV, liver disease/portal hypertension, CHD, drug exposures, family history.",
      "Consider genetic counselling/testing when indicated (BMPR2 and PAH gene panel).",
      "Vasoreactivity testing only for idiopathic/heritable/drug-associated PAH in an expert centre.",
      "Baseline WHO-FC, 6MWD, BNP/NT-proBNP, RV imaging and hemodynamics."
    ),
    "Left heart disease / Group 2" = c(
      "Echo: LV systolic/diastolic function, LA size and valvular disease.",
      "Assess HFpEF/HFrEF phenotype, congestion, AF, obesity, hypertension and ischemia.",
      "RHC if diagnosis uncertain or results affect advanced management; consider fluid challenge / provocative testing at expert centre."
    ),
    "Lung disease / Group 3" = c(
      "PFT, DLCO, HRCT, resting/exertional oxygenation and ABG when appropriate.",
      "Assess ILD/COPD, hypoventilation and sleep-related respiratory disease.",
      "Consider RHC for severe/disproportionate PH (e.g., suspected PVR >5 WU), transplant evaluation or therapeutic decisions."
    ),
    "CTEPH / Group 4" = c(
      "V/Q scan (preferably SPECT if available); evaluate mismatched perfusion defects.",
      "CTPA and expert pulmonary vascular imaging for lesion distribution.",
      "RHC and multidisciplinary operability assessment at a CTEPH centre.",
      "Assess anticoagulation history and antiphospholipid syndrome when appropriate."
    ),
    "Multifactorial / Group 5" = c(
      "Identify hematologic, systemic (e.g., sarcoidosis), metabolic and complex congenital contributors.",
      "Exclude concurrent LHD, lung disease and CTEPH.",
      "Individualized work-up and multidisciplinary PH centre review."
    )
  )

  output$investigation_out <- renderUI({
    tagList(lapply(investigations[[input$suspect]], function(x) div(class = "step", x)))
  })

  output$treatment_out <- renderUI({
    g <- input$group
    r <- input$risk

    x <- switch(
      g,
      "Not classified" = c(
        "Do not select PAH-targeted treatment before establishing hemodynamics and likely PH group.",
        "Refer to diagnostic and investigation pathways."
      ),
      "Group 1 — PAH" = c(
        "Confirm PAH subtype, cardiopulmonary comorbidities, and baseline/follow-up risk in an expert centre.",
        "Without cardiopulmonary comorbidities: initial oral dual combination therapy (ERA + PDE5 inhibitor) is recommended for low or intermediate baseline risk.",
        "With cardiopulmonary comorbidities: initial oral monotherapy (PDE5 inhibitor or ERA) is recommended; individualize add-on therapy under expert review.",
        "For high-risk disease: initial triple combination therapy including a parenteral prostacyclin analogue and urgent transplant evaluation.",
        if (r %in% c("Intermediate-low", "Intermediate-high", "High")) {
          "2026 ERS: add-on sotatercept is recommended for patients already on background PAH therapy at intermediate-low through high follow-up risk; specialist monitoring (Hb, platelets, bleeding risk) required."
        } else if (r == "Low") {
          "2026 ERS: continue current therapy and regular follow-up; no recommendation for routine sotatercept add-on in low-risk PAH."
        } else {
          "Select follow-up risk (4-strata) above to view risk-dependent escalation and sotatercept add-on guidance."
        },
        "Safety: Never combine PDE5 inhibitors with riociguat (hypotension risk). High-dose CCB is strictly reserved for confirmed positive acute vasoreactivity in eligible PAH subtypes. (See Drugs tab for formulary & dosing details)."
      ),
      "Group 2 — Left heart disease" = c(
        "Optimize guideline-directed heart failure treatment (including SGLT2i/diuretics), volume status, rhythm control, and valvular management.",
        "Do not routinely use PAH-targeted vasodilators; sildenafil was harmful in SIOVAC after corrected valve disease, and macitentan/riociguat showed no clear benefit with potential fluid retention.",
        "Refer disproportionate/severe CpcPH (PVR >5 WU) for individualized assessment at an expert centre."
      ),
      "Group 3 — Lung disease / hypoxia" = c(
        "Optimize underlying lung disease, long-term oxygen therapy when indicated, pulmonary rehabilitation, and transplant assessment as appropriate.",
        "Inhaled treprostinil (INCREASE trial) may be considered for PH associated with ILD where approved, under specialist review.",
        "Do not extrapolate PH-ILD benefit to PH-COPD: inhaled treprostinil in PH-COPD (PERFECT trial) raised safety concerns. Avoid riociguat in PH associated with idiopathic interstitial pneumonia (RISE-IIP).",
        "Severe PH in lung disease (PVR >5 WU) warrants referral to a PH centre for individualized decision-making."
      ),
      "Group 4 — CTEPH" = c(
        "Lifelong therapeutic anticoagulation is recommended (vitamin K antagonists preferred in antiphospholipid syndrome).",
        "All confirmed CTEPH patients require multidisciplinary operability assessment at an expert CTEPH centre: pulmonary endarterectomy (PEA) is the treatment of choice for operable disease.",
        "For inoperable CTEPH or persistent/recurrent PH after PEA: consider balloon pulmonary angioplasty (BPA) and/or medical therapy (riociguat; subcutaneous treprostinil may be considered in WHO-FC III–IV).",
        "Multimodal therapy (PEA, BPA, and targeted medical therapy) may be combined sequentially by a dedicated CTEPH team."
      ),
      "Group 5 — Multifactorial" = c(
        "Treat the underlying disorder and contributing pathophysiological mechanisms.",
        "Exclude coexisting treatable causes including CTEPH and left heart congestion.",
        "PAH-targeted therapy is not routinely recommended; consider only on an individualized basis at an expert centre."
      )
    )

    tagList(
      lapply(x, function(y) div(class = "step", y)),
      div(
        class = "alert-note",
        "This is a summary pathway, not a prescription. Confirm drug approval, contraindications, interactions, teratogenicity/pregnancy prevention, and monitoring in the full guideline."
      )
    )
  })

  output$drugs_out <- renderUI({
    pw <- input$drug_pathway
    filtered <- if (is.null(pw) || pw == "all") {
      drugs_data
    } else {
      Filter(function(d) identical(d$pathway, pw), drugs_data)
    }

    cards <- lapply(filtered, function(d) {
      div(
        class = "drug-card",
        div(
          class = "drug-header",
          span(class = "drug-name", d$name),
          span(class = "drug-badge", d$group_label)
        ),
        div(
          class = "th-avail",
          strong("Thailand availability: "),
          d$en_status
        ),
        div(
          style = "font-size:13.5px;margin-bottom:5px;",
          strong("Typical adult dosing: "),
          d$dosing_en
        ),
        div(
          style = "font-size:13.5px;margin-bottom:5px;",
          strong("Key adverse effects: "),
          d$side_effects_en
        ),
        div(
          style = "font-size:13.5px;color:#8a2a2a;",
          strong("Contraindications, interactions & monitoring: "),
          d$cautions_en
        )
      )
    })

    tagList(
      cards,
      div(
        class = "alert-note",
        "Note: Dosing and formulary status are provided for rapid clinical reference only. Always verify renal/hepatic dose adjustments, drug-drug interactions, pregnancy prevention requirements, and current institutional reimbursement criteria before prescribing."
      )
    )
  })

  output$references <- renderUI({
    tagList(
      lapply(seq_len(nrow(refs)), function(i) {
        d <- refs$doi[i]
        div(
          class = "step",
          strong(refs$name[i]),
          br(),
          tags$a(href = paste0("https://doi.org/", d), target = "_blank", d),
          " · ",
          tags$a(
            href = paste0("https://pubmed.ncbi.nlm.nih.gov/?term=", utils::URLencode(d, reserved = TRUE)),
            target = "_blank",
            "PubMed"
          )
        )
      })
    )
  })
